[{'name': 'Check out detection scripts', 'uses': 'actions/checkout@v4', 'with': {'sparse-checkout': '.github/scripts'}}, {'name': 'Detect milestone', 'id': 'detect', 'env': {'MODE': "${{ github.event.inputs.mode
    || (github.event.schedule == '0 7 * * *' && 'current')
    || (github.event.schedule == '0 17 * * *' && 'latest')
    || 'next' }}", 'MILESTONE': '${{ github.event.inputs.milestone }}', 'GH_TOKEN': '${{ github.token }}'}, 'run': 'bash .github/scripts/skia-sync-detect.sh --gate --mode "$MODE" --milestone "$MILESTONE"'}]; [{'name': 'Select issue to triage', 'id': 'find-issue', 'env': {'INPUT_ISSUE': '${{ github.event.inputs.issue_number }}', 'GH_TOKEN': '${{ github.token }}'}, 'run': 'if [ -n "$INPUT_ISSUE" ]; then
  echo "issue_number=$INPUT_ISSUE" >> "$GITHUB_OUTPUT"
  exit 0
fi
CUTOFF=$(date -u -d '1 hour ago' +%Y-%m-%dT%H:%M:%SZ)
ISSUE=$(gh issue list --repo "$GITHUB_REPOSITORY" \
  --state open \
  --search "-label:triage/triaged created:<${CUTOFF} sort:comments-desc" \
  --json number --limit 1 --jq '.[0].number')
if [ -z "$ISSUE" ] || [ "$ISSUE" = "null" ]; then
  echo "::notice::No untriaged issues older than 1 hour"
  exit 1
fi
echo "issue_number=$ISSUE" >> "$GITHUB_OUTPUT"
'}]; [{'name': 'Confirm exact /review tests command', 'id': 'exact_command', 'env': {'EVENT_NAME': '${{ github.event_name }}', 'COMMENT_BODY': '${{ github.event.comment.body }}', 'ISSUE_PULL_REQUEST_URL': '${{ github.event.issue.pull_request.url }}'}, 'run': 'if [ "$EVENT_NAME" = "workflow_dispatch" ]; then
  echo "should_run=true" >> "$GITHUB_OUTPUT"; exit 0
fi
if [ "$EVENT_NAME" != "issue_comment" ] || [ -z "${ISSUE_PULL_REQUEST_URL:-}" ]; then
  echo "should_run=false" >> "$GITHUB_OUTPUT"; exit 0
fi
if [[ "$COMMENT_BODY" =~ ^[[:space:]]*/review[[:space:]]+tests[[:space:]]*$ ]]; then
  echo "should_run=true" >> "$GITHUB_OUTPUT"
else
  echo "should_run=false" >> "$GITHUB_OUTPUT"
fi
'}, {'name': 'Hide the /review tests command comment as resolved when authorized', 'if': "github.event_name == 'issue_comment' && steps.exact_command.outputs.should_run == 'true'", 'uses': 'actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3', 'with': {'github-token': '${{ github.token }}', 'script': "// Only hide when the command is exactly `/review tests` (should_run) AND the
// commenter is an authorized collaborator (write/maintain/admin). This mirrors
// the workflow's own role gate but is self-contained, so an unauthorized user's
// comment is always left visible. A failed hide must not block activation.
// Only act on newly-created comments. The gh-aw slash_command trigger also fires
// on `edited`, so without this guard, editing any existing comment to say
// `/review tests` would minimize that comment (and collapse its entire history).
if (context.payload.action !== 'created') {
  core.info('Skipping hide: comment was edited, not created.');
  return;
}
const { owner, repo } = context.repo;
const actor = context.actor;
let permission = 'none';
try {
  const res = await github.rest.repos.getCollaboratorPermissionLevel({ owner, repo, username: actor });
  permission = res.data.permission;
} catch (e) {
  core.info(`Permission lookup for ${actor} failed: ${e.message}`);
}
// Must mirror the workflow `roles:` frontmatter (admin/maintain/write) — keep in sync.
if (!['admin', 'maintain', 'write'].includes(permission)) {
  core.info(`Actor ${actor} is not an authorized collaborator (${permission}); leaving the /review tests comment.`);
  return;
}
// Minimize (hide as resolved) rather than delete: the rerun scanner replays the PR's
// REST comment history, and minimized comments are still returned by the REST list
// endpoint — only collapsed in the web UI. node_id is the comment's GraphQL global id.
const subjectId = context.payload.comment.node_id;
try {
  await github.graphql(
    `mutation($id: ID!) {
       minimizeComment(input: { subjectId: $id, classifier: RESOLVED }) {
         minimizedComment { isMinimized }
       }
     }`,
    { id: subjectId }
  );
  core.info(`Hid /review tests command comment ${subjectId} as resolved.`);
} catch (e) {
  core.warning(`Could not hide /review tests command comment ${subjectId}: ${e.message}`);
}
"}}]

"// Only hide when the command is exactly `/review tests` (should_run) AND the
// commenter is an authorized collaborator (write/maintain/admin). This mirrors
// the workflow's own role gate but is self-contained, so an unauthorized user's
// comment is always left visible. A failed hide must not block activation.
// Only act on newly-created comments. The gh-aw slash_command trigger also fires
// on `edited`, so without this guard, editing any existing comment to say
// `/review tests` would minimize that comment (and collapse its entire history).
if (context.payload.action !== 'created') {
  core.info('Skipping hide: comment was edited, not created.');
  return;
}
const { owner, repo } = context.repo;
const actor = context.actor;
let permission = 'none';
try {
  const res = await github.rest.repos.getCollaboratorPermissionLevel({ owner, repo, username: actor });
  permission = res.data.permission;
} catch (e) {
  core.info(`Permission lookup for ${actor} failed: ${e.message}`);
}
// Must mirror the workflow `roles:` frontmatter (admin/maintain/write) — keep in sync.
if (!['admin', 'maintain', 'write'].includes(permission)) {
  core.info(`Actor ${actor} is not an authorized collaborator (${permission}); leaving the /review tests comment.`);
  return;
}
// Minimize (hide as resolved) rather than delete: the rerun scanner replays the PR's
// REST comment history, and minimized comments are still returned by the REST list
// endpoint — only collapsed in the web UI. node_id is the comment's GraphQL global id.
const subjectId = context.payload.comment.node_id;
try {
  await github.graphql(
    `mutation($id: ID!) {
       minimizeComment(input: { subjectId: $id, classifier: RESOLVED }) {
         minimizedComment { isMinimized }
       }
     }`,
    { id: subjectId }
  );
  core.info(`Hid /review tests command comment ${subjectId} as resolved.`);
} catch (e) {
  core.warning(`Could not hide /review tests command comment ${subjectId}: ${e.message}`);
}
"; "const pr = context.payload.pull_request.number;
// Remove trigger label
try {
  await github.rest.issues.removeLabel({
    ...context.repo,
    issue_number: pr,
    name: 'architecture-review-needed'
  });
} catch (e) {
  core.warning(`Could not remove trigger label: ${e.message}`);
