// Add in-progress label
try {
  await github.rest.issues.addLabels({
    ...context.repo,
    issue_number: pr,
    labels: ['architecture-review-in-progress']
  });
} catch (e) {
  core.warning(`Could not add in-progress label: ${e.message}`);
}
